-- Universal Loader (all games)
-- Auto-detects the game and runs the matching script.
-- Opens SM2 Discord first, then loads the matching hub.

--------------------------------------------------------------------
-- SM2 Scripts — Discord join gate (runs once per session)
-- Opens Discord (app when possible, otherwise browser), asks them to join,
-- then continues loading the hub after they confirm.
--------------------------------------------------------------------
do
	local genv = (getgenv and getgenv()) or _G
	if not genv.__SM2_DISCORD_GATE_DONE then
		genv.__SM2_DISCORD_GATE_DONE = true

		local INVITE = "https://discord.gg/5dKGSfqwHj"
		local INVITE_CODE = "5dKGSfqwHj"
		-- Opens the Discord desktop/mobile app straight to the invite screen
		local DISCORD_APP = "discord://-/invite/" .. INVITE_CODE
		local DISCORD_WEB = "https://discord.com/invite/" .. INVITE_CODE

		local function tryOpenUrl(url)
			if type(url) ~= "string" or url == "" then
				return false
			end

			local opened = false

			-- Executor helpers (most reliable for discord:// and https)
			local candidates = {
				rawget(_G, "open_url"),
				rawget(_G, "openurl"),
				rawget(_G, "opentab"),
				rawget(_G, "OpenUrl"),
				rawget(_G, "openbrowser"),
				rawget(_G, "OpenBrowser"),
				rawget(_G, "open_browser"),
				rawget(genv, "open_url"),
				rawget(genv, "openurl"),
				rawget(genv, "OpenUrl"),
				rawget(genv, "openbrowser"),
			}
			for _, fn in ipairs(candidates) do
				if typeof(fn) == "function" then
					local ok = pcall(fn, url)
					if ok then
						opened = true
					end
				end
			end

			pcall(function()
				if syn and typeof(syn.open_url) == "function" then
					syn.open_url(url)
					opened = true
				end
			end)

			pcall(function()
				if fluxus and typeof(fluxus.open_url) == "function" then
					fluxus.open_url(url)
					opened = true
				end
			end)

			-- Roblox system browser (https; custom schemes often ignored)
			pcall(function()
				local GuiService = game:GetService("GuiService")
				if GuiService and typeof(GuiService.OpenBrowserWindow) == "function" then
					GuiService:OpenBrowserWindow(url)
					opened = true
				end
			end)

			return opened
		end

		local function openDiscord()
			pcall(function()
				if setclipboard then
					setclipboard(INVITE)
				elseif toclipboard then
					toclipboard(INVITE)
				end
			end)

			-- Try Discord app first, then web invite (fire all — “ok” ≠ actually opened)
			tryOpenUrl(DISCORD_APP)
			tryOpenUrl(INVITE)
			tryOpenUrl(DISCORD_WEB)
			return true
		end

		print("[SM2] Opening Discord → " .. INVITE)
		openDiscord()

		-- Blocking join prompt (script waits until they continue)
		pcall(function()
			local Players = game:GetService("Players")
			local StarterGui = game:GetService("StarterGui")
			local lp = Players.LocalPlayer
			local pg = lp and (lp:FindFirstChild("PlayerGui") or lp:WaitForChild("PlayerGui", 5))
			if not pg then
				task.wait(2.5)
				return
			end

			local done = false
			local gui = Instance.new("ScreenGui")
			gui.Name = "SM2_DiscordGate"
			gui.ResetOnSpawn = false
			gui.IgnoreGuiInset = true
			gui.DisplayOrder = 999999
			gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
			gui.Parent = pg

			local dim = Instance.new("Frame")
			dim.Size = UDim2.fromScale(1, 1)
			dim.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
			dim.BackgroundTransparency = 0.35
			dim.BorderSizePixel = 0
			dim.Parent = gui

			local card = Instance.new("Frame")
			card.AnchorPoint = Vector2.new(0.5, 0.5)
			card.Position = UDim2.fromScale(0.5, 0.5)
			card.Size = UDim2.fromOffset(420, 260)
			card.BackgroundColor3 = Color3.fromRGB(18, 18, 22)
			card.BorderSizePixel = 0
			card.Parent = gui
			Instance.new("UICorner", card).CornerRadius = UDim.new(0, 12)

			local accent = Instance.new("Frame")
			accent.Size = UDim2.new(1, 0, 0, 4)
			accent.BackgroundColor3 = Color3.fromRGB(88, 101, 242) -- Discord blurple
			accent.BorderSizePixel = 0
			accent.Parent = card
			Instance.new("UICorner", accent).CornerRadius = UDim.new(0, 12)

			local title = Instance.new("TextLabel")
			title.BackgroundTransparency = 1
			title.Position = UDim2.fromOffset(24, 28)
			title.Size = UDim2.new(1, -48, 0, 32)
			title.Font = Enum.Font.GothamBold
			title.TextSize = 24
			title.TextXAlignment = Enum.TextXAlignment.Left
			title.TextColor3 = Color3.fromRGB(255, 255, 255)
			title.Text = "Join SM2 Scripts Discord"
			title.Parent = card

			local body = Instance.new("TextLabel")
			body.BackgroundTransparency = 1
			body.Position = UDim2.fromOffset(24, 68)
			body.Size = UDim2.new(1, -48, 0, 70)
			body.Font = Enum.Font.Gotham
			body.TextSize = 15
			body.TextWrapped = true
			body.TextXAlignment = Enum.TextXAlignment.Left
			body.TextYAlignment = Enum.TextYAlignment.Top
			body.TextColor3 = Color3.fromRGB(190, 190, 200)
			body.Text =
				"Discord should open automatically.\nJoin the server, then click Continue to load the script.\n\nInvite: "
					.. INVITE
			body.Parent = card

			local function makeBtn(text, xScale, color)
				local b = Instance.new("TextButton")
				b.AnchorPoint = Vector2.new(0.5, 0)
				b.Position = UDim2.new(xScale, 0, 1, -64)
				b.Size = UDim2.fromOffset(170, 40)
				b.BackgroundColor3 = color
				b.BorderSizePixel = 0
				b.Font = Enum.Font.GothamBold
				b.TextSize = 15
				b.TextColor3 = Color3.fromRGB(255, 255, 255)
				b.Text = text
				b.AutoButtonColor = true
				b.Parent = card
				Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
				return b
			end

			local openBtn = makeBtn("Open Discord", 0.28, Color3.fromRGB(88, 101, 242))
			local continueBtn = makeBtn("I Joined — Continue", 0.72, Color3.fromRGB(40, 170, 90))

			openBtn.MouseButton1Click:Connect(function()
				openDiscord()
				body.Text =
					"Opening Discord…\nJoin the server, then click Continue.\n\nInvite copied: "
						.. INVITE
			end)

			continueBtn.MouseButton1Click:Connect(function()
				done = true
			end)

			pcall(function()
				StarterGui:SetCore("SendNotification", {
					Title = "SM2 Scripts",
					Text = "Opening Discord — join, then Continue",
					Duration = 6,
				})
			end)

			-- Retry open after UI shows (some executors only work after a frame)
			task.delay(0.2, function()
				if not done then
					openDiscord()
				end
			end)
			task.delay(0.8, function()
				if not done then
					openDiscord()
				end
			end)

			-- Wait until they click Continue (cap at 90s so scripts never soft-lock forever)
			local t0 = os.clock()
			while not done and (os.clock() - t0) < 90 do
				task.wait(0.1)
			end

			gui:Destroy()
		end)
	end
end

