local function join(t)
	local s = ""
	for i = 1, #t do
		s = s .. t[i]
	end
	return s
end
local function b64decode(data)
	local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	data = string.gsub(data, "[^" .. b .. "=]", "")
	return (
		data:gsub(".", function(x)
			if x == "=" then return "" end
			local r, f = "", (b:find(x) - 1)
			for i = 6, 1, -1 do
				r = r .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
			end
			return r
		end)
		:gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
			if #x ~= 8 then return "" end
			local c = 0
			for i = 1, 8 do
				c = c + (x:sub(i, i) == "1" and 2 ^ (8 - i) or 0)
			end
			return string.char(c)
		end)
	)
end
local function bxor(a, b)
	if bit32 and bit32.bxor then return bit32.bxor(a, b) end
	if bit and bit.bxor then return bit.bxor(a, b) end
	local r, bitv = 0, 1
	while a > 0 or b > 0 do
		local aa, bb = a % 2, b % 2
		if aa ~= bb then r = r + bitv end
		a, b, bitv = (a - aa) / 2, (b - bb) / 2, bitv * 2
	end
	return r
end
local function run(payload, key, label)
	local raw = b64decode(join(payload))
	local out = {}
	for i = 1, #raw do
		out[i] = string.char(bxor(string.byte(raw, i), key))
	end
	local src = table.concat(out)
	local fn, err = loadstring(src)
	if not fn then error("[Universal] " .. tostring(label) .. " compile: " .. tostring(err)) end
	fn()
end

local MurderPlaces = {[120851538706364]=true}
local KnifePlaces = {[112731528776884]=true}
local FlickPlaces = {[136801880565837]=true}
local EntrenchedPlaces = {[3678761576]=true}
local SniperPlaces = {[109397169461300]=true}
local BedWarsPlaces = {[6872265039]=true,[6872274481]=true}
local ViolencePlaces = {[93978595733734]=true}
local TycoonPlaces = {[125496078313264]=true}
local MM2Places = {[142823291]=true}
local PhantomPlaces = {[292439477]=true}
local RivalsPlaces = {[17625359962]=true,[17720162456]=true}
local TTKPlaces = {[120189115846709]=true}
local function getPlaceName()
	local n = tostring(game.Name or "")
	pcall(function()
		local info = game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId)
		if info and info.Name then n = info.Name end
	end)
	return string.lower(n)
end
local function detect()
	local id = game.PlaceId
	if RivalsPlaces[id] then return "rivals" end
	if PhantomPlaces[id] then return "phantom" end
	if MM2Places[id] then return "mm2" end
	if ViolencePlaces[id] then return "violence" end
	if TycoonPlaces[id] then return "tycoon" end
	if BedWarsPlaces[id] then return "bedwars" end
	if SniperPlaces[id] then return "sniper" end
	if EntrenchedPlaces[id] then return "entrenched" end
	if FlickPlaces[id] then return "flick" end
	if KnifePlaces[id] then return "knife" end
	if MurderPlaces[id] then return "murder" end
	if TTKPlaces[id] then return "ttk" end
	local n = getPlaceName()
	if string.find(n, "rivals", 1, true) then return "rivals" end
	if string.find(n, "phantom forces", 1, true) or (string.find(n, "phantom", 1, true) and string.find(n, "force", 1, true)) then
		return "phantom"
	end
	if string.find(n, "murder mystery", 1, true) then return "mm2" end
	if string.find(n, "violence district", 1, true) or string.find(n, "violence", 1, true) and string.find(n, "district", 1, true) then
		return "violence"
	end
	if string.find(n, "evolution tycoon", 1, true) or (string.find(n, "evolution", 1, true) and string.find(n, "tycoon", 1, true)) then
		return "tycoon"
	end
	if string.find(n, "bedwars", 1, true) or string.find(n, "bed wars", 1, true) then
		return "bedwars"
	end
	if string.find(n, "sniper", 1, true) and string.find(n, "duel", 1, true) then
		return "sniper"
	end
	if string.find(n, "entrenched", 1, true) then return "entrenched" end
	if string.find(n, "flick", 1, true) then return "flick" end
	if string.find(n, "knife", 1, true) and string.find(n, "duel", 1, true) then
		return "knife"
	end
	if string.find(n, "murder", 1, true) and string.find(n, "duel", 1, true) then
		return "murder"
	end
	if string.find(n, "ttk", 1, true) then return "ttk" end
	return nil
end

